[snr, signal_power, noise_power, total_loss] = uplink([10:5:90,10:5:90],[170e3*ones(1,length(10:5:90)),420e3*ones(1,length(10:5:90))],10e3) %[output:66286c5e] %[output:970b0807] %[output:3b863d8d] %[output:912a1160]
radar_rx_power_max = 10*log10(5e6) - total_loss %[output:650df2fb]
radar_rx_power_min = 10*log10(1e6) - total_loss %[output:45c149c1]
figure %[output:71653c6d]
hold on %[output:71653c6d]
plot(10:5:90,signal_power(1:17),"DisplayName","Alt=170km") %[output:71653c6d]
plot(10:5:90,signal_power(18:end),"DisplayName","Alt=420km") %[output:71653c6d]
plot(10:5:90,noise_power*ones(length(10:5:90),1),"DisplayName","Noise") %[output:71653c6d]

title("Received Signal Power @ 10kHz BW By Altitude") %[output:71653c6d]
xlabel("Elevation (Degrees)") %[output:71653c6d]
ylabel("P (dBW)") %[output:71653c6d]
legend %[output:71653c6d]

figure %[output:049af6cc]
hold on %[output:049af6cc]
plot(10:5:90,signal_power(1:17),      "DisplayName","Alt=170km") %[output:049af6cc]
plot(10:5:90,radar_rx_power_max(1:17),"DisplayName","Fylingdales Max"); %[output:049af6cc]
plot(10:5:90,radar_rx_power_min(1:17),"DisplayName","Fylingdales Min"); %[output:049af6cc]

plot(10:5:90,noise_power*ones(length(10:5:90),1),"DisplayName","Noise") %[output:049af6cc]

title("Received Signal Power @ 10kHz BW By Altitude") %[output:049af6cc]
xlabel("Elevation (Degrees)") %[output:049af6cc]
ylabel("P (dBW)") %[output:049af6cc]
legend %[output:049af6cc]
figure %[output:610eb7a9]
hold on %[output:610eb7a9]
plot(10:5:90,signal_power(1:17)       - noise_power,"DisplayName","Alt=170km") %[output:610eb7a9]
plot(10:5:90,radar_rx_power_max(1:17) - noise_power,"DisplayName","Fylingdales Max"); %[output:610eb7a9]
plot(10:5:90,radar_rx_power_min(1:17) - noise_power,"DisplayName","Fylingdales Min"); %[output:610eb7a9]


title("Received SNR @ 10kHz BW By Altitude") %[output:610eb7a9]
xlabel("Elevation (Degrees)") %[output:610eb7a9]
ylabel("SNR (dB)") %[output:610eb7a9]
legend %[output:610eb7a9]
%[text] Doppler Shift
sat_doppler_420 = dopplerShiftCircularOrbit(10:5:180,420e3,38,437e6);
sat_doppler_170 = dopplerShiftCircularOrbit(10:5:180,170e3,38,437e6);

figure %[output:621aa460]
hold on %[output:621aa460]
plot(10:5:180,sat_doppler_420/1e3, "DisplayName","420km") %[output:621aa460]
plot(10:5:180,sat_doppler_170/1e3, "DisplayName","170km") %[output:621aa460]
legend %[output:621aa460]
ylabel("Doppler Shift (kHz)") %[output:621aa460]
xlabel("Elevation Angle (Degrees)") %[output:621aa460]
%[text] SIR elevation to STAC and elevation to Fylingdales
elevs = 0:5:90;
f = 437e6;
altsat = 170e3;
bw = 10e3;
rad_power = 10*log10(5e6);

[el_sat,el_rad] = meshgrid(10:5:90);
sir = zeros(size(el_sat));

for el_sat_it = 1:length(el_sat)
    for el_rad_it = 1:length(el_rad)
        sat_snr = uplink(el_sat_it,altsat,bw);
        [~, ~, ~, rad_loss] = uplink(el_rad_it,altsat,bw);
        sir(el_sat_it,el_rad_it) = sat_snr - (rad_power - rad_loss - noise_power);
    end
end

figure %[output:6590144a]
contour(el_sat,el_rad,sir) %[output:6590144a]
ylabel("Elevation to Ground Station") %[output:6590144a]
xlabel("Elevation to Fylingdales Radar") %[output:6590144a]
xticks([elevs]) %[output:6590144a]
yticks([elevs]) %[output:6590144a]
cb = colorbar; %[output:6590144a]
cb.Label.String = 'SINR (dB)'; %[output:6590144a]

